#include <bits/stdc++.h>
using namespace std;
int main(){
  int n;
  cin>>n;
  vector<bool> sq(n+1,false);
  for(int i=1;i*i<=n;i++) sq[i*i]=true;
  vector<vector<int>> d(n+1);
  for(int i=1;i<=n;i++){
    for(int j=i;j<=n;j+=i) d[j].push_back(i);
  }
  vector<int> cnt(n+1);
  for(int i=1;i<=n;i++){
    int f=0;
    for(int j=0;j<d[i].size();j++) if(sq[d[i][j]]) f=d[i][j];
    cnt[i/f]++;
  }
  int ans=0;
  for(int i=1;i<=n;i++) ans+=cnt[i]*cnt[i];
  cout<<ans<<endl;
}

import java.util.*;

class Main {
    public static void main(String args[]) {
        var sc = new Scanner(System.in);
        int n = sc.nextInt();
        var d = new int[n + 1];
        Arrays.setAll(d, i -> i);
        for (int i = 2; i * i <= n; i++) {
            if (d[i] != i)
                continue;
            int ii = i * i;
            for (int j = ii; j <= n; j += ii)
                while (d[j] % ii == 0)
                    d[j] /= ii;
        }
        var h = new int[n + 1];
        for (int i = 1; i * i <= n; i++)
            h[i * i]++;
        Arrays.parallelPrefix(h, Integer::sum);
        long ans = 0L;
        for (int i = 1; i <= n; i++)
            ans += h[n / d[i]];
        System.out.println(ans);
        sc.close();
    }
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int N;
    cin >> N;
    int sqrt_N = sqrt(N);

    // 線形篩で前計算 Θ(√N)時間
    vector<int> primes, least_prime_factor(sqrt_N + 1);
    for(int i = 2; i <= sqrt_N; ++i){
        if(!least_prime_factor[i]){
            primes.emplace_back(i);
            least_prime_factor[i] = i;
        }
        for(const auto p : primes){
            if(p * i > sqrt_N || p > least_prime_factor[i])break;
            least_prime_factor[p * i] = p;
        }
    }

    // φ(2), φ(3), ..., φ(Floor(√N)) を線形篩を用いて計算 Θ(√N)時間
    vector<int> totient(sqrt_N + 1);
    for(int i = 2; i <= sqrt_N; ++i){
        const auto p = least_prime_factor[i];
        totient[i] = i == p ? i - 1
                   : least_prime_factor[i / p] == p ? p * totient[i / p]
                   : (p - 1) * totient[i / p];
    }

    // 答えは 2 * ∑ Floor(N/i²) φ(i) + N
    int ans = 0;
    for(int i = 2; i <= sqrt_N; ++i)ans += N / i / i * totient[i];
    cout << 2 * ans + N << endl;

    return 0;
}

#define ll long long
int main(){
	int n;
	scanf("%d",&n);
	ll ans=0;
	for(ll i=1;i<=n;i++){
		ll k=i;
		for(ll d=2;d*d<=k;d++){
			while(k%(d*d)==0)k/=d*d;
		}
		for(ll d=1;k*d*d<=n;d++)ans++;
	}
	printf("%lld",ans);
}
